"use client";

import { useEffect, useState, type CSSProperties } from "react";

import { renderFlatSkin } from "../core";
import type { SteveModelVariant } from "../core/steveGeo";

export interface FlatSkinProps {
  textureUrl: string | null | undefined;
  variant?: SteveModelVariant;
  scale?: number;
  alt?: string;
  className?: string;
  style?: CSSProperties;
}

export function FlatSkin({
  textureUrl,
  variant,
  scale = 16,
  alt = "Minecraft skin",
  className,
  style,
}: FlatSkinProps) {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    if (!textureUrl) {
      setUrl(null);
      return;
    }
    let cancelled = false;
    renderFlatSkin(textureUrl, { variant, scale })
      .then((rendered) => {
        if (!cancelled) setUrl(rendered);
      })
      .catch(() => {
        if (!cancelled) setUrl(null);
      });
    return () => {
      cancelled = true;
    };
  }, [textureUrl, variant, scale]);

  if (!url) return null;

  return (
    <img
      src={url}
      alt={alt}
      className={className}
      draggable={false}
      style={{
        width: "100%",
        height: "100%",
        objectFit: "contain",
        imageRendering: "pixelated",
        userSelect: "none",
        ...style,
      }}
    />
  );
}
